test_vmaxfp128_1:
  # v3 = [10.0, -10.0, 15.0, -15.0]
  # v4 = [-10.0, 20.0, -20.0, 30.0]
  #_ REGISTER_IN v3 [41200000, C1200000, 41700000, C1700000]
  #_ REGISTER_IN v4 [C1200000, 41A00000, C1A00000, 41F00000]
  vmaxfp128 v0, v3, v4
  blr
  #_ REGISTER_OUT v0 [41200000, 41A00000, 41700000, 41F00000]
  #_ REGISTER_OUT v3 [41200000, C1200000, 41700000, C1700000]
  #_ REGISTER_OUT v4 [C1200000, 41A00000, C1A00000, 41F00000]

test_vmaxfp128_nan:
  # Match Xenia's single maxps lowering: if either operand is NaN, the second source is returned.
  #_ REGISTER_IN v3 [7FC00000, 3F800000, 7FC00000, C0000000]
  #_ REGISTER_IN v4 [3F800000, 7FC00000, 7FA00001, C0400000]
  vmaxfp128 v0, v3, v4
  blr
  #_ REGISTER_OUT v0 [3F800000, 7FC00000, 7FA00001, C0000000]
  #_ REGISTER_OUT v3 [7FC00000, 3F800000, 7FC00000, C0000000]
  #_ REGISTER_OUT v4 [3F800000, 7FC00000, 7FA00001, C0400000]
